        const written = (await repos2.questions.byLevel(level.levelNumber)).filter((q) => q.status === "approved" && q.mode === "written");
        const picked = written.slice(setNo * QUESTIONS_PER_CONCEPT, (setNo + 1) * QUESTIONS_PER_CONCEPT);
